{
  "root_causes": [
    {
      "service": "ts-seat-service",
      "fault_kind": "http_slow",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT p.span_name pspan, c.service_name callee, c.span_name cspan, count(*) n, round(avg(p.duration::DOUBLE)/1e6,1) caller_ms, round(avg(c.duration::DOUBLE)/1e6,1) callee_ms FROM abnormal_traces p JOIN abnormal_traces c ON c.parent_span_id = p.span_id AND c.trace_id = p.trace_id WHERE p.service_name='ts-seat-service' AND p.attr_span_kind='Client' GROUP BY ALL ORDER BY caller_ms DESC",
          "claim": "Seat's POST to order /order/tickets averages 2908ms caller-side while order's server span takes 4.4ms."
        },
        {
          "kind": "trace",
          "sql": "SELECT p.service_name caller, c.service_name callee, c.span_name cspan, count(*) n, round(avg(p.duration::DOUBLE)/1e6,1) caller_ms, round(avg(c.duration::DOUBLE)/1e6,1) callee_ms FROM abnormal_traces p JOIN abnormal_traces c ON c.parent_span_id = p.span_id AND c.trace_id = p.trace_id WHERE p.service_name='ts-seat-service' AND p.attr_span_kind='Client' AND c.service_name IN ('ts-order-other-service','ts-config-service') GROUP BY ALL",
          "claim": "Same seat pod's calls to order-other and config stay fast (about 25ms and 15ms), so only the order/tickets path is slow."
        },
        {
          "kind": "metric",
          "sql": "SELECT metric, attr_source, attr_destination, count(*) n, round(avg(value),1) avg_v FROM abnormal_metrics_sum WHERE metric='hubble_http_requests_total' AND attr_source LIKE '%ts-seat-service%' GROUP BY ALL ORDER BY avg_v DESC",
          "claim": "Hubble shows seat-to-order request values rising (about 3065 vs 2007 normal) while seat's other connections are less affected."
        }
      ]
    }
  ],
  "propagation": [
    {
      "from": "ts-seat-service",
      "to": "ts-travel-service",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT p.service_name caller, c.service_name callee, c.span_name cspan, count(*) n, round(avg(p.duration::DOUBLE)/1e6,1) caller_ms, round(avg(c.duration::DOUBLE)/1e6,1) callee_ms FROM abnormal_traces p JOIN abnormal_traces c ON c.parent_span_id = p.span_id AND c.trace_id = p.trace_id WHERE p.service_name='ts-travel-service' AND p.attr_span_kind='Client' AND c.service_name='ts-seat-service' GROUP BY ALL",
          "claim": "Travel's POST to seat left_tickets averages about 2959ms, matching seat's slow server time."
        }
      ]
    },
    {
      "from": "ts-seat-service",
      "to": "ts-preserve-service",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT p.service_name caller, c.service_name callee, c.span_name cspan, count(*) n, round(avg(p.duration::DOUBLE)/1e6,1) caller_ms, round(avg(c.duration::DOUBLE)/1e6,1) callee_ms FROM abnormal_traces p JOIN abnormal_traces c ON c.parent_span_id = p.span_id AND c.trace_id = p.trace_id WHERE p.service_name='ts-preserve-service' AND p.attr_span_kind='Client' AND c.service_name='ts-seat-service' GROUP BY ALL",
          "claim": "Preserve's POST to seat /seats averages about 2941ms, so preserve inherits the seat delay."
        }
      ]
    },
    {
      "from": "ts-travel-service",
      "to": "ts-route-plan-service",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT p.service_name caller, c.service_name callee, c.span_name cspan, count(*) n, round(avg(p.duration::DOUBLE)/1e6,1) caller_ms, round(avg(c.duration::DOUBLE)/1e6,1) callee_ms FROM abnormal_traces p JOIN abnormal_traces c ON c.parent_span_id = p.span_id AND c.trace_id = p.trace_id WHERE p.service_name='ts-route-plan-service' AND p.attr_span_kind='Client' AND c.service_name='ts-travel-service' AND c.span_name LIKE '%trips/left%' GROUP BY ALL",
          "claim": "Route-plan's POST to travel trips/left averages about 7586ms, matching travel's slow server time."
        }
      ]
    },
    {
      "from": "ts-route-plan-service",
      "to": "ts-travel-plan-service",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT p.service_name caller, c.service_name callee, c.span_name cspan, count(*) n, round(avg(p.duration::DOUBLE)/1e6,1) caller_ms, round(avg(c.duration::DOUBLE)/1e6,1) callee_ms FROM abnormal_traces p JOIN abnormal_traces c ON c.parent_span_id = p.span_id AND c.trace_id = p.trace_id WHERE p.service_name='ts-travel-plan-service' AND p.attr_span_kind='Client' AND c.service_name='ts-route-plan-service' GROUP BY ALL",
          "claim": "Travel-plan's POST calls to route-plan routePlan endpoints average 5-10 seconds, mirroring route-plan's server time."
        }
      ]
    },
    {
      "from": "ts-travel-plan-service",
      "to": "ts-ui-dashboard",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT span_name, service_name, count(*) n, round(avg(duration::DOUBLE)/1e6,1) avg_ms FROM abnormal_traces WHERE service_name='ts-ui-dashboard' AND attr_span_kind='Server' AND span_name LIKE '%travelPlan%' GROUP BY ALL",
          "claim": "User-facing ui-dashboard travelPlan endpoints show multi-second server latency during the incident."
        }
      ]
    },
    {
      "from": "ts-preserve-service",
      "to": "ts-ui-dashboard",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT span_name, service_name, count(*) n, round(avg(duration::DOUBLE)/1e6,1) avg_ms FROM abnormal_traces WHERE service_name='ts-ui-dashboard' AND attr_span_kind='Server' AND span_name LIKE '%preserve%' GROUP BY ALL",
          "claim": "The ui-dashboard preserve endpoint averages about 9 seconds server-side during the incident."
        }
      ]
    }
  ]
}
